if (typeof d3 !== 'undefined' && typeof d3.parliament === 'function') {
    var width = 500;
    var height = 500;
    var screenWidth = contentDiv.offsetWidth || 500;

    if (screenWidth < width - 50) {
        width = Math.max(260, screenWidth - 50);
        height = width;
        var svg = document.getElementById('bloc_1986_chamber');
        if (svg) {
            svg.style.width = width + 'px';
            svg.style.height = (screenWidth / 2) + 'px';
        }
    }

    var parliament = d3.parliament();
    parliament.width(width).height(height).innerRadiusCoef(0.4);
    parliament.enter.fromCenter(true).smallToBig(true);
    parliament.exit.toCenter(false).bigToSmall(true);
    d3.select('#bloc_1986_chamber').datum(data).call(parliament);

    // Dynamic already knows SPD/CVP/BVP/RDP/DNVP. Only custom ending parties need explicit fills.
    d3.select('#bloc_1986_chamber').selectAll('.seat.lspd').style('fill','#BE3075');
    d3.select('#bloc_1986_chamber').selectAll('.seat.csrp').style('fill','#FF7F00');
    d3.select('#bloc_1986_chamber').selectAll('.seat.nlp').style('fill','#98C22C');
    d3.select('#bloc_1986_chamber').selectAll('.seat.ndpd').style('fill','#D79E2A');

    // No player-party ring or dot borders.
    d3.select('#bloc_1986_chamber').selectAll('.seat')
        .style('stroke','none')
        .style('stroke-width','0');
}

